name: Continue Agents
on:
  workflow_call:
    inputs:
      agents-path:
        description: "Path to continue agents directory"
        required: false
        default: ".continue/agents"
        type: string

jobs:
  run-agents:
    name: Run Continue Agents
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: "20"

      - name: Install Continue CLI
        run: |
          npm install -g @continuedev/cli

      - name: Discover agents
        id: discover
        run: |
          AGENT_FILES=$(find "${{ inputs.agents-path }}" -name "*.md" -type f | sort)
          echo "agent_files<<EOF" >> $GITHUB_OUTPUT
          echo "$AGENT_FILES" >> $GITHUB_OUTPUT
          echo "EOF" >> $GITHUB_OUTPUT
          echo "agent_count=$(echo "$AGENT_FILES" | wc -l)" >> $GITHUB_OUTPUT

      - name: Run agents
        if: steps.discover.outputs.agent_count > 0
        id: run_agents
        uses: actions/github-script@v7
        with:
          script: |
            const fs = require('fs');
            const path = require('path');
            const { exec } = require('child_process');

            const agentFiles = `${{ steps.discover.outputs.agent_files }}`.split('\n').filter(f => f.trim() !== '');

            // Create job summary header
            let jobSummary = '# Continue Agents Results\n\n';

            // Run each agent in parallel
            const promises = agentFiles.map(async (agentFile) => {
              const agentName = path.basename(agentFile, '.md');
              const agentPath = path.relative(process.cwd(), agentFile);

              // Create check run
              const checkRun = await github.rest.checks.create({
                owner: context.repo.owner,
                repo: context.repo.repo,
                name: `Continue Agent: ${agentName}`,
                head_sha: context.sha,
                status: 'in_progress',
                details_url: `https://github.com/${context.repo.owner}/${context.repo.repo}/blob/${context.sha}/${agentPath}`
              });

              const checkRunId = checkRun.data.id;

              try {
                // Run the agent
                const result = await new Promise((resolve, reject) => {
                  const child = exec(`continue run --file "${agentFile}"`, { encoding: 'utf8' }, (error, stdout, stderr) => {
                    if (error) {
                      reject(new Error(`Agent failed: ${stderr || error.message}`));
                    } else {
                      resolve({ stdout, stderr });
                    }
                  });

                  // Capture output for check run
                  child.stdout.on('data', (data) => {
                    // Update check run with partial output
                    github.rest.checks.update({
                      owner: context.repo.owner,
                      repo: context.repo.repo,
                      check_run_id: checkRunId,
                      output: {
                        title: `Continue Agent: ${agentName}`,
                        summary: `Agent execution in progress`,
                        text: data
                      }
                    }).catch(() => {}); // Ignore errors updating check run
                  });
                });

                // Update check run with success
                await github.rest.checks.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  check_run_id: checkRunId,
                  conclusion: 'success',
                  completed_at: new Date().toISOString(),
                  output: {
                    title: `Continue Agent: ${agentName}`,
                    summary: `Agent executed successfully`,
                    text: result.stdout
                  }
                });

                // Add to job summary
                jobSummary += `## ✅ ${agentName}\n\`\`\`\n${result.stdout}\n\`\`\`\n\n`;

                return { name: agentName, success: true, output: result.stdout };
              } catch (error) {
                // Update check run with failure
                await github.rest.checks.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  check_run_id: checkRunId,
                  conclusion: 'failure',
                  completed_at: new Date().toISOString(),
                  output: {
                    title: `Continue Agent: ${agentName}`,
                    summary: `Agent execution failed`,
                    text: error.message
                  }
                });

                // Add to job summary
                jobSummary += `## ❌ ${agentName}\n\`\`\`\n${error.message}\n\`\`\`\n\n`;

                throw error;
              }
            });

            // Wait for all agents to complete
            try {
              await Promise.all(promises);
              // Write job summary
              await core.summary.addRaw(jobSummary).write();
            } catch (error) {
              // Write job summary even on failure
              await core.summary.addRaw(jobSummary).write();
              throw error;
            }

      - name: Show job summary
        if: always()
        run: |
          echo "Job Summary:"
          cat ${{ github.workspace }}/.github/job-summary.md

      - name: Fail if any agent failed
        if: failure()
        run: |
          echo "One or more agents failed. See job summary for details."
          exit 1
